package com.mint.rebuilt;
import android.app.*;
import android.os.*;
import android.content.*;
import android.provider.Settings;
import android.net.Uri;
import android.text.InputFilter;
import android.widget.*;
import android.view.*;
import java.util.*;
import org.json.*;
public final class SettingsActivity extends Activity {
 private final Map<String,Switch> flags=new LinkedHashMap<String,Switch>();private final Map<String,EditText> fields=new LinkedHashMap<String,EditText>();private LinearLayout column;
 @Override public void onCreate(Bundle b){super.onCreate(b);setTitle("Configurações");build();}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private void build(){try{flags.clear();fields.clear();JSONObject c=new JSONObject(ConfigNative.json(this));ScrollView scroll=new ScrollView(this);column=new LinearLayout(this);column.setOrientation(1);column.setPadding(dp(20),dp(12),dp(20),dp(24));scroll.addView(column);setContentView(scroll);TextView title=new TextView(this);title.setText("Configurações");title.setTextSize(24);column.addView(title);flag(c,"usernameEnabled","Gerar usuário da 888");field(c,"usernameLength","Quantidade de caracteres do usuário",2,2);flag(c,"usernameAlphanumeric","Usuário alfanumérico");flag(c,"passwordEnabled","Preencher senha de acesso");field(c,"password","Senha de acesso",129,1024);flag(c,"pinEnabled","Preencher senha de saque");field(c,"pin","Senha de saque · 6 dígitos",18,6);flag(c,"historyEnabled","Histórico de bombas do Mines");field(c,"historyRounds","Rodadas do histórico · 1 a 100",2,3);flag(c,"wagerEnabled","Contador do total apostado");button("Proxy · HTTP / HTTPS / SOCKS5",new Runnable(){public void run(){ProxySettings.show(SettingsActivity.this);}});button("✓ Aplicar",new Runnable(){public void run(){apply();}});button("Restaurar padrão",new Runnable(){public void run(){new AlertDialog.Builder(SettingsActivity.this).setTitle("Restaurar padrão?").setMessage("Ativar as funções, usar usuário de 15 caracteres, histórico de 10 rodadas, limpar senhas e remover o proxy?").setNegativeButton("Cancelar",null).setPositiveButton("Restaurar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){if(ConfigNative.restoreDefaults(SettingsActivity.this))build();else toast("Não foi possível restaurar.");}}).show();}});if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)button("Permitir notificação do proxy",new Runnable(){public void run(){Intent i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}});TextView note=new TextView(this);note.setText("As opções permanecem após Limpar dados. As senhas começam vazias. O bloqueio de anúncios fica sempre ativo. O CAPTCHA é manual. Proxy controlado pela notificação.");note.setTextSize(13);note.setPadding(0,dp(16),0,dp(10));column.addView(note);button("Voltar",new Runnable(){public void run(){finish();}});}catch(Exception e){toast("Não foi possível carregar as opções.");finish();}}
 private void flag(JSONObject c,String key,String label){Switch s=new Switch(this);s.setText(label);s.setTextSize(16);s.setChecked(c.optBoolean(key,true));s.setPadding(0,dp(10),0,dp(10));s.setMinHeight(dp(52));column.addView(s);flags.put(key,s);}
 private void field(JSONObject c,String key,String label,int type,int limit){TextView t=new TextView(this);t.setText(label);t.setPadding(0,dp(12),0,0);column.addView(t);EditText e=new EditText(this);e.setSingleLine();e.setInputType(type);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limit)});e.setText(key.equals("usernameLength")||key.equals("historyRounds")?String.valueOf(c.optInt(key)):c.optString(key,""));e.setSelectAllOnFocus(true);column.addView(e,new LinearLayout.LayoutParams(-1,-2));fields.put(key,e);}
 private void button(String label,final Runnable run){Button b=new Button(this);b.setText(label);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){run.run();}});column.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));}
 private void apply(){try{JSONObject c=new JSONObject(ConfigNative.json(this));for(Map.Entry<String,Switch> e:flags.entrySet())c.put(e.getKey(),e.getValue().isChecked());for(Map.Entry<String,EditText> e:fields.entrySet()){String k=e.getKey(),v=e.getValue().getText().toString();if(k.equals("usernameLength")||k.equals("historyRounds")){int n;try{n=Integer.parseInt(v.trim());}catch(Exception x){n=0;}int max=k.equals("historyRounds")?100:64;if(n<1||n>max){e.getValue().setError("Use de 1 a "+max);return;}c.put(k,n);}else{if(k.equals("pin")&&!v.isEmpty()&&!v.matches("[0-9]{6}")){e.getValue().setError("Use 6 dígitos ou deixe vazio");return;}c.put(k,v);}}toast(ConfigNative.save(this,c.toString())?"Configurações aplicadas.":"Não foi possível aplicar as configurações.");}catch(Exception e){toast("Confira os campos e tente novamente.");}}
 private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 @Override protected void onResume(){super.onResume();ProxyService.ensure(this);}
}
